const sceneGroups=[['','Gemeinsame Schnellwahl'],['tiktok','TikTok · Hochformat'],['twitch','Twitch · Querformat']];
function fallbackSceneOrder(a,b){const rank=item=>{const name=String(item.name||item.label||'').toLocaleLowerCase('de').replace(/[_-]/g,' ').replace(/\b(tiktok|twitch|tt|hochformat|querformat)\b/g,'').trim();const i=['start','spiel','pause','chat','ende','offline','pc'].indexOf(name);return i<0?99:i;};return rank(a)-rank(b)||String(a.name||a.label).localeCompare(String(b.name||b.label),'de',{numeric:true,sensitivity:'base'});}
function sceneOptions(){
 const scenes=(config?.obsCollection?.scenes||[]).filter(s=>!s.internal),provided=state?.sceneChoices;
 if(provided)return provided.map(choice=>{const scene=scenes.find(s=>s.key===choice.value);return scene?{name:scene.name,platform:scene.platform,...choice}:choice;});
 return [...builtins.map(value=>({value,label:value,name:value})).sort(fallbackSceneOrder),...['tiktok','twitch'].flatMap(platform=>scenes.filter(s=>s.platform===platform).sort(fallbackSceneOrder).map(s=>{const partner=scenes.find(p=>p.id===s.partnerId&&p.platform!==platform);return {value:s.key,label:s.label||s.name,name:s.name,platform,spokenName:labels[platform]+' '+s.name,partnerLabel:partner?.label||partner?.name,partnerName:partner?.name,partnerKey:partner?.key};}))];
}
function sceneSelectOptions(){const choices=sceneOptions();return sceneGroups.map(([platform,title])=>{const items=choices.filter(item=>(item.platform||'')===platform);return items.length?`<optgroup label="${esc(title)}">${items.map(item=>`<option value="${esc(item.value)}">${esc(item.name||item.label)}</option>`).join('')}</optgroup>`:'';}).join('');}
function sceneLabel(value=config?.program.scene){return sceneOptions().find(s=>s.value===value)?.label||value||'';}
function transitionOptions(){const items=state?.transitionChoices||[{id:'fade',name:'Überblenden',type:'fade'},{id:'cut',name:'Schnitt',type:'cut'},...(config?.transitions||[])];return items.map(item=>({...item,id:item.id||item.value,name:item.name||item.label||item.id||item.value})).filter((item,index,all)=>item.id&&all.findIndex(other=>other.id===item.id)===index);}
function transitionNote(){if(!config)return;const selectedTransition=transitionOptions().find(item=>item.id===$('transition').value),type=selectedTransition?.type||selectedTransition?.id;$('transition-note').textContent=type==='stinger'?'„'+selectedTransition.name+'“ nutzt dein OBS-Übergangsvideo. Länge und Umschaltpunkt stammen aus OBS. Jarvis: „Übergang auf '+selectedTransition.name+'“. Die sparsame Vorschau zeigt nur 1 Bild/s; der vollständige Übergang wird über die virtuelle Kamera ausgegeben.':type==='cut'?'Schnitt wechselt sofort zur gewählten Szene.':'Überblenden verwendet die eingestellte Dauer. „Übergang speichern“ übernimmt die Auswahl auch für Jarvis und die Szenentasten.';}
function importedScene(value=config?.program.scene,platform=selected){const library=config?.obsCollection,scenes=library?.scenes||[],id=library?.aliases?.[platform]?.[value];const chosen=scenes.find(s=>s.key===value||s.id===id);if(!chosen)return null;return chosen.platform===platform?chosen:scenes.find(s=>s.id===chosen.partnerId)||chosen;}
function outputName(platform=selected){return importedScene(config?.program.scene,platform)?.name||sceneLabel();}
function editingShared(){return previewMode==='sources'||config?.program.scene==='Spiel'&&!importedScene();}

const visible=()=>!window.BattoResources?.suspended&&!document.hidden&&document.getElementById('view-dualstream').classList.contains('active');
