async function api(command,value){return window.batto.dual(command,value);}
function run(fn){return async event=>{event?.preventDefault();if(busy)return;busy=true;status();try{await fn(event);}catch(e){const text=String(e.message).replace(/^Error invoking remote method '[^']+': (?:Error: )?/,'');message(text);if($('obs-dialog')?.open)$('obs-status').textContent=text;if($('obs-local-dialog')?.open)$('obs-local-status').textContent=text;}finally{busy=false;status();schedulePreview();}};}
