 $('transition').onchange=()=>{transitionNote();status();};
 on('transition-save',async()=>{const transition=$('transition').value,durationMs=Number($('transition-ms').value);if(dirty)await save();adopt(await api('program',{...state.config.program,transition,durationMs,baseRevision}));message('Übergang „'+(transitionOptions().find(item=>item.id===config.program.transition)?.name||config.program.transition)+'“ für Szenentasten und Jarvis gespeichert.');});
 on('scene-apply',()=>chooseScene($('scene').value));on('show-game',()=>{previewMode='sources';$('preview-mode').value='sources';invalidatePreview();canvas();status();schedulePreview(0);});
 const removeImport=async(kind,id)=>{
  const node=kind==='scene'?config.obsCollection?.scenes.find(s=>s.key===id):kind==='source'?config.obsCollection?.sources.find(s=>s.id===id):config.transitions?.find(t=>t.id===id),name=node?.label||node?.name||'';
  const prompt=kind==='all'?'Alle importierten OBS-Szenen, Medien und Übergänge aus Dual Stream entfernen?':kind==='scene'?'OBS-Szene „'+name+'“ aus Dual Stream entfernen?':kind==='source'?'Medienquelle „'+name+'“ aus allen importierten Szenen entfernen?':'OBS-Übergang „'+name+'“ entfernen?';
  if(!confirm(prompt+'\nDie Originaldateien und deine OBS-Sammlung bleiben auf dem PC erhalten.'))return;
  clearTimeout(sourceTimer);invalidatePreview(false);if(dirty)await save();adopt(await api('obs-import-remove',{kind,id,baseRevision}));message(kind==='all'?'OBS-Importe aus Dual Stream entfernt.':'„'+name+'“ aus Dual Stream entfernt.');
 };
 $('collection').addEventListener('click',run(async event=>{const remove=event.target.closest('[data-obs-remove]');if(remove){await removeImport(remove.dataset.obsRemove,remove.dataset.obsId);return;}const button=event.target.closest('[data-imported-scene]');if(button)await chooseScene(button.dataset.importedScene);}));
