 on('import',async()=>{if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen und ein Projekt importieren?'))return;const next=await api('import');if(next){adopt(next);message('Projekt übernommen. Aufnahmequellen bitte zuordnen.');}});
 const chooseObsFile=async()=>{if(dirty)await save();const next=await api('obs-import-preview');if(next){$('obs-local-dialog').close();showObsImport(next);}};on('obs-import',chooseObsFile);
 on('obs-local',async()=>{const result=await api('obs-import-list'),collections=result.collections||[];$('obs-local-select').innerHTML=collections.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('');$('obs-local-status').textContent=collections.length?(result.truncated?'Es werden die ersten 100 Sammlungen angezeigt. Weitere Sammlungen kannst du als JSON-Datei auswählen.':'Sammlung auswählen und „Szenen prüfen“ drücken.'): 'Keine OBS-Sammlung gefunden. In OBS unter „Szenensammlung → Exportieren“ speichern und anschließend „JSON-Datei auswählen“ drücken.';$('obs-local-dialog').showModal();});
