 $('workspace').hidden=delegated;$('detached-note').hidden=!delegated;$('detach').hidden=detached||delegated;$('attach').hidden=!detached;$('top-label').hidden=!detached;$('top').checked=state.alwaysOnTop===true;$('reload').hidden=!conflict;for(const id of ['import','obs-import','obs-local','export','save','dirty'])$(id).hidden=delegated;
 if(delegated){clearTimeout(sourceTimer);invalidatePreview();if($('canvas').querySelector('img'))canvas();}
